pragma solidity ^0.8.0;

import {Script} from "forge-std/Script.sol";
import {IDiamondPackageCallBackFactory} from "@crane/contracts/interfaces/IDiamondPackageCallBackFactory.sol";
import {IERC20} from "@crane/contracts/interfaces/IERC20.sol";
import {IDiamondLoupe} from "@crane/contracts/interfaces/IDiamondLoupe.sol";
import {IPostDeployAccountHook} from "@crane/contracts/interfaces/IPostDeployAccountHook.sol";
import {IVaultRegistryDeployment} from "contracts/interfaces/IVaultRegistryDeployment.sol";
import {IDETFSYDFPkg} from "contracts/vaults/detf/common/sy/IDETFSYDFPkg.sol";
import {IUniswapV4DetfMigrationDFPkg as Package} from "contracts/vaults/detf/protocols/dexes/uniswap/v4/migration/interfaces/IUniswapV4DetfMigrationDFPkg.sol";
import {IUniswapV4DetfMigrationSYDFPkg as SyPackage} from "contracts/vaults/detf/protocols/dexes/uniswap/v4/migration/sy/IUniswapV4DetfMigrationSYDFPkg.sol";
import {UniswapV4DetfMigration_Pkg_FactoryService as Packages} from "contracts/vaults/detf/protocols/dexes/uniswap/v4/migration/UniswapV4DetfMigration_Pkg_FactoryService.sol";
import {IUniswapV4DetfMigration as Migration} from "contracts/vaults/detf/protocols/dexes/uniswap/v4/migration/interfaces/IUniswapV4DetfMigration.sol";

/// @notice Local receipt witness using already replayed, source-bound CREATE3/registry infrastructure.
/// @dev Simulate on the owned historical fork, then submit each generated transaction with
/// gas=32000000. The enclosing script's gas and the simulation are not transaction receipts.
contract MigrationDeploymentGasLocalQA is Script {
    address private constant DEV = 0xf39Fd6e51aad88F6F4ce6aB8827279cffFb92266;
    event PackagesDeployed(address indexed parentPackage, address syPackage);
    event InstanceDeployed(address indexed parent, address owner, address rawSy, address stakingSy);

    function deployPackages(IVaultRegistryDeployment registry_, IDiamondPackageCallBackFactory factory_,
        Package.PkgInit memory init_, IDETFSYDFPkg.PkgInit memory syInit_) external
    {
        require(block.chainid == 4663 && tx.origin == DEV, "owned historical witness");
        require(address(init_.baseInit.vaultRegistryDeployment) == address(registry_)
            && address(syInit_.vaultRegistryDeployment) == address(registry_), "actual registry");
        vm.startBroadcast(DEV);
        SyPackage sy_ = Packages.deploySy(registry_, SyPackage.MigrationPkgInit(syInit_, factory_));
        init_.baseInit.syPkg = sy_;
        Package parent_ = Packages.deployParent(registry_, init_);
        vm.stopBroadcast();
        require(parent_.syPackage() == address(sy_) && address(sy_.diamondFactory()) == address(factory_),
            "immutable selected dependencies");
        emit PackagesDeployed(address(parent_), address(sy_));
    }

    function construct(Package package_, Package.PkgArgs memory args_) external {
        require(block.chainid == 4663 && tx.origin == DEV, "owned historical witness");
        Package.SyConstruction memory c_ = package_.syConstruction(args_);
        require(c_.parent.code.length == 0, "fresh parent");
        vm.startBroadcast(DEV);
        (address raw_, address staking_) = package_.prepareSyChildren(args_);
        vm.stopBroadcast();
        require(c_.parent.code.length == 0 && c_.bond.code.length == 0 && c_.receipt.code.length == 0,
            "only SY children prepared");
        require(IERC20(raw_).totalSupply() == 0 && IERC20(staking_).totalSupply() == 0, "zero prepared supply");
        require(IDiamondLoupe(raw_).facetAddress(IPostDeployAccountHook.postDeploy.selector) == address(0)
            && IDiamondLoupe(staking_).facetAddress(IPostDeployAccountHook.postDeploy.selector) == address(0),
            "complete prepared children");
        vm.startBroadcast(DEV);
        address parent_ = package_.deployVault(args_);
        vm.stopBroadcast();
        Migration p_ = Migration(parent_);
        require(parent_ == c_.parent && p_.owner() == args_.owner && p_.hook() == args_.baseArgs.hook,
            "canonical parent");
        require(p_.bondNftVault() == c_.bond && p_.rebasingClaimToken() == c_.receipt
            && p_.rawSY() == raw_ && p_.stakingSY() == staking_, "canonical children");
        require(p_.migrationSyRewardToken().code.length != 0 && IERC20(parent_).totalSupply() == 0
            && !p_.migrationActivated(), "complete Stage1 instance");
        require(IDiamondLoupe(parent_).facetAddress(IPostDeployAccountHook.postDeploy.selector) == address(0),
            "complete parent");
        emit InstanceDeployed(parent_, args_.owner, raw_, staking_);
    }
}
